<?php use App\Support\Http;use App\Controllers\AuthController;$e=static fn($s)=>Http::escape((string)$s);$url=static fn($s)=>Http::escape(AuthController::url($s));$csrf=$e($_SESSION['csrf_token']); ?>
<!doctype html><html lang="<?= \App\Support\I18n::locale() ?>"><head><?php require APP_ROOT.'/app/Views/localization-head.php'; ?><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= \App\Support\I18n::html('Offline sales review | Dharma Chemical') ?></title><link rel="stylesheet" href="<?= $url('/assets/vendor/bootstrap/bootstrap.min.css') ?>"><link rel="stylesheet" href="<?= $url('/assets/css/app.css') ?>"></head><body class="workspace"><?php require APP_ROOT.'/app/Views/workspace-header.php'; ?><main class="container py-4"><a href="<?= $url('/admin') ?>"><?= \App\Support\I18n::html('Admin dashboard') ?></a><h1 class="h2 my-3"><?= \App\Support\I18n::html('Offline sales & device review') ?></h1><?php if($notice): ?><p class="alert alert-success"><?= \App\Support\I18n::html($notice) ?></p><?php endif; ?><p><?= \App\Support\I18n::html('Provisional collections are not payments until their sale is accepted. A rejection requires external stock/cash reconciliation; this screen never executes a refund or changes agreed prices.') ?></p><form method="get" class="row g-2 my-3"><div class="col-md-7"><label for="sync-search" class="form-label"><?= \App\Support\I18n::html('Search sale reference, device or representative') ?></label><input id="sync-search" name="q" maxlength="100" class="form-control" value="<?= $e(is_string($_GET['q']??null)?$_GET['q']:'') ?>"></div><div class="col-md-3"><label for="sync-status" class="form-label"><?= \App\Support\I18n::html('Sale status') ?></label><select id="sync-status" name="status" class="form-select"><?php foreach([''=>'All statuses','RECEIVED'=>'Needs Attention','ACCEPTED'=>'Synced','REJECTED'=>'Rejected'] as $key=>$label): ?><option value="<?= $key ?>" <?= ($_GET['status']??'')===$key?'selected':'' ?>><?= \App\Support\I18n::html($label) ?></option><?php endforeach; ?></select></div><div class="col-md-2 align-self-end"><button class="btn btn-primary"><?= \App\Support\I18n::html('Filter') ?></button><a href="<?= $url('/admin/offline') ?>"><?= \App\Support\I18n::html('Reset Filters') ?></a></div></form><h2 class="h4"><?= \App\Support\I18n::html('Registered devices (not filtered)') ?></h2><?php foreach($listing['devices'] as $d): ?><section class="card card-body my-3"><h3 class="h5"><?= $e($d['name'].' — '.$d['label']) ?></h3><p class="small"><?= $e($d['id']) ?> · <?= $d['revoked_at_utc']?\App\Support\I18n::html('Revoked'):\App\Support\I18n::html('Active') ?> <?= \App\Support\I18n::html('· Last sync UTC') ?> <?= $e($d['last_sync_at_utc']??\App\Support\I18n::html('Never')) ?></p><?php if(!$d['replacement_cleared_at_utc']): ?><form method="post" action="<?= $url('/admin/offline/devices/'.$d['id']) ?>"><input type="hidden" name="csrf_token" value="<?= $csrf ?>"><input type="hidden" name="action" value="<?= $d['revoked_at_utc']?'RELEASE':'REVOKE' ?>"><label class="form-label" for="device-<?= $e($d['id']) ?>"><?= \App\Support\I18n::html('Mandatory reason / reconciliation reference') ?></label><textarea class="form-control mb-3" name="reason" id="device-<?= $e($d['id']) ?>" maxlength="2000" required></textarea><?php if($d['revoked_at_utc']): ?><label class="form-check mb-3"><input class="form-check-input" name="reconciled" type="checkbox" value="1" required> <?= \App\Support\I18n::html('I reconciled all physical stock, collected cash and unuploaded sales, including any lost device records. Unknown offline activity has been investigated.') ?></label><?php endif; ?><button class="btn btn-outline-danger"><?= $d['revoked_at_utc']?\App\Support\I18n::html('Permit replacement after reconciliation'):\App\Support\I18n::html('Revoke device now') ?></button></form><?php else: ?><p><?= \App\Support\I18n::html('Replacement reconciliation recorded. Old-device sales can never automatically post.') ?></p><?php endif; ?></section><?php endforeach; ?>
<h2 class="h4 mt-5"><?= \App\Support\I18n::html('Offline submissions (unresolved first)') ?></h2><?php if(!$listing['sales']): ?><p><?= \App\Support\I18n::html('No offline sales have been submitted.') ?></p><?php endif; ?><?php foreach($listing['sales'] as $s): $p=json_decode($s['body_json'],true); ?><section class="card card-body my-3"><h3 class="h5"><?= $e($s['name']) ?> · <?= $e($s['result_status']==='ACCEPTED'?\App\Support\I18n::html('Synced'):($s['result_status']==='REJECTED'?\App\Support\I18n::html('Rejected'):\App\Support\I18n::html('Needs Attention'))) ?></h3><p class="small"><?= \App\Support\I18n::html('Local reference') ?> <?= $e($s['id']) ?> <?= \App\Support\I18n::html('· Device') ?> <?= $e($s['device_id']) ?></p><p><?= \App\Support\I18n::html('Agreed total LKR') ?> <?= $e($p['grand_total']??\App\Support\I18n::html('Invalid')) ?> <?= \App\Support\I18n::html('· Provisional cash collected LKR') ?> <?= $e($p['amount_received']??\App\Support\I18n::html('Invalid')) ?></p><p><?= $e($s['last_error_message']??\App\Support\I18n::html('Accepted without repricing.')) ?></p><details><summary><?= \App\Support\I18n::html('Preserved signed sale data') ?></summary><pre class="text-wrap"><?= $e(json_encode($p,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></details><?php if($s['result_status']==='ACCEPTED'): ?><a href="<?= $url('/admin/invoices/'.$s['id']) ?>"><?= \App\Support\I18n::html('Open accepted invoice') ?></a><?php endif; ?><?php foreach($s['reviews'] as $review): ?><div class="border rounded p-3 mt-3"><strong><?= $e($review['action'].' — '.$review['reviewer']) ?></strong><p class="small"><?= $e($review['created_at_utc']) ?> <?= \App\Support\I18n::html('UTC') ?></p><p><?= $e($review['reason']) ?></p><p><?= \App\Support\I18n::html('External reconciliation reference:') ?> <?= $e($review['cash_reconciliation_note']??\App\Support\I18n::html('Not applicable')) ?></p></div><?php endforeach; ?><?php if($s['result_status']==='RECEIVED'): ?><form method="post" action="<?= $url('/admin/offline/sales/'.$s['id']) ?>" class="mt-3"><input type="hidden" name="csrf_token" value="<?= $csrf ?>"><label for="review-<?= $e($s['id']) ?>" class="form-label"><?= \App\Support\I18n::html('Review decision') ?></label><select class="form-select mb-3" name="action" id="review-<?= $e($s['id']) ?>"><option value="RETRY"><?= \App\Support\I18n::html('Retry strict unchanged-term validation') ?></option><option value="REJECT"><?= \App\Support\I18n::html('Reject after external stock/cash reconciliation') ?></option></select><label class="form-label" for="reason-<?= $e($s['id']) ?>"><?= \App\Support\I18n::html('Mandatory review reason') ?></label><textarea id="reason-<?= $e($s['id']) ?>" class="form-control mb-3" name="reason" maxlength="2000" required></textarea><label class="form-label" for="cash-<?= $e($s['id']) ?>"><?= \App\Support\I18n::html('External stock/cash reconciliation reference (required for rejection)') ?></label><textarea id="cash-<?= $e($s['id']) ?>" class="form-control mb-3" name="cash_reconciliation_note" maxlength="2000"></textarea><label class="form-check mb-3"><input class="form-check-input" type="checkbox" name="reconciled" value="1"> <?= \App\Support\I18n::html('For rejection: stock was not delivered or has been physically returned, and the provisional cash has been reconciled externally. No refund is being executed here.') ?></label><button class="btn btn-primary"><?= \App\Support\I18n::html('Record authorized review') ?></button></form><?php endif; ?></section><?php endforeach; ?><nav aria-label="<?= \App\Support\I18n::html('Offline review pages') ?>"><?php foreach([-1=>'Previous',1=>'Next'] as $delta=>$label): $target=$listing['page']+$delta;if($target<1||$target>$listing['pages'])continue; ?><a class="me-3" href="<?= $url('/admin/offline?'.http_build_query(array_merge($_GET,['page'=>$target]))) ?>"><?= \App\Support\I18n::html($label) ?></a><?php endforeach; ?><?= \App\Support\I18n::html('Page') ?> <?= $e($listing['page']) ?> <?= \App\Support\I18n::html('of') ?> <?= $e($listing['pages']) ?></nav></main><?php require APP_ROOT.'/app/Views/workspace-footer.php'; ?></body></html>
